# PTX source for fp16 matrix multiplication (A[M,K] * B[K,N] = C[M,N])
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry kernel_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
{
    // Load parameters
    .reg .u64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u32 %M, %K, %N;
    ld.param.u64 %a_ptr, [A_ptr];
    ld.param.u64 %b_ptr, [B_ptr];
    ld.param.u64 %c_ptr, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %K, [K];
    ld.param.u32 %N, [N];

    // Thread / block indices (builtin registers)
    // %tid.x, %tid.y, %ctaid.x, %ctaid.y are .u32
    // Compute global row and column (each thread = one output element)
    .reg .u32 %row, %col;
    mad.lo.u32 %row, %ctaid.y, 16, %tid.y;   // row = blockIdx.y*16 + threadIdx.y
    mad.lo.u32 %col, %ctaid.x, 16, %tid.x;   // col = blockIdx.x*16 + threadIdx.x

    // Boundary check
    .reg .pred %p_out;
    setp.ge.u32 %p_out, %row, %M;
    @%p_out bra DONE;
    setp.ge.u32 %p_out, %col, %N;
    @%p_out bra DONE;

    // Accumulator in fp32
    .reg .f32 %acc;
    mov.f32 %acc, 0f00000000;   // 0.0f

    // Loop over K dimension
    .reg .u32 %k;
    .reg .pred %p_done;
    mov.u32 %k, 0;
LOOP_K:
    setp.ge.u32 %p_done, %k, %K;
    @%p_done bra END_LOOP_K;

    // Compute address of A[row, k]
    .reg .u64 %addr_a, %addr_b, %tmp64;
    mul.wide.u32 %tmp64, %row, %K;          // row * K (64‑bit)
    add.u64 %tmp64, %tmp64, %k;            // row*K + k
    shl.b64 %addr_a, %tmp64, 1;            // *sizeof(half)=2
    add.u64 %addr_a, %addr_a, %a_ptr;      // + base pointer

    // Compute address of B[k, col]
    mul.wide.u32 %tmp64, %k, %N;           // k * N
    add.u64 %tmp64, %tmp64, %col;          // k*N + col
    shl.b64 %addr_b, %tmp64, 1;            // *2
    add.u64 %addr_b, %addr_b, %b_ptr;      // + base pointer

    // Load half values
    .reg .f16 %a_val, %b_val;
    ld.global.f16 %a_val, [%addr_a];
    ld.global.f16 %b_val, [%addr_b];

    // Convert to fp32
    .reg .f32 %a_f32, %b_f32;
    cvt.f32.f16 %a_f32, %a_val;
    cvt.f32.f16 %b_f32, %b_val;

    // MAC
    mad.f32 %acc, %a_f32, %b_f32, %acc;

    // k++
    add.u32 %k, %k, 1;
    bra LOOP_K;
END_LOOP_K:

    // Convert accumulator back to half
    .reg .f16 %c_val;
    cvt.f16.f32 %c_val, %acc;

    // Store C[row, col]
    .reg .u64 %addr_c;
    mul.wide.u32 %tmp64, %row, %N;          // row * N
    add.u64 %tmp64, %tmp64, %col;          // row*N + col
    shl.b64 %addr_c, %tmp64, 1;            // *2
    add.u64 %addr_c, %addr_c, %c_ptr;      // + base pointer
    st.global.f16 [%addr_c], %c_val;

DONE:
    ret;
}
