# ModelNew class that launches the PTX kernel
# --------------------------------------------------------------
import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A: [M, K] float16 tensor on CUDA
        B: [K, N] float16 tensor on CUDA
        Returns C: [M, N] float16 tensor on CUDA
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"

        # Allocate output
        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # Kernel launch configuration (16x16 thread block)
        block = (16, 16, 1)
        grid = ((N + 15) // 16, (M + 15) // 16, 1)

        # Arguments: raw device pointers and dimensions (as 64‑bit integers for pointers,
        # 32‑bit integers for sizes)
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            K,
            N
        ]

        # Launch the PTX kernel
        ptx_launch(self.module, "kernel_matmul", grid, block, args)

